/**
 * Export the Mooduel mood dataset from Supabase into release formats.
 *
 * Writes:
 *   dataset/mooduel-v1.0.jsonl   (one movie per line)
 *   dataset/mooduel-v1.0.csv     (spreadsheet/pandas friendly)
 *
 * Parquet is generated by HuggingFace automatically when the dataset is
 * uploaded. If you want a local parquet file, run:
 *   duckdb -c "COPY (SELECT * FROM read_json_auto('dataset/mooduel-v1.0.jsonl')) \
 *             TO 'dataset/mooduel-v1.0.parquet' (FORMAT PARQUET)"
 *
 * Usage: npx tsx scripts/export-dataset.ts
 */

import { createClient } from "@supabase/supabase-js";
import { writeFileSync, mkdirSync, existsSync } from "fs";
import { resolve } from "path";
import { config } from "dotenv";

config({ path: resolve(__dirname, "../.env.local") });

const DATASET_VERSION = "1.0";
const PAGE = 1000;

const supabase = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL!,
  process.env.SUPABASE_SERVICE_ROLE_KEY!
);

type Row = Record<string, unknown>;

function toCsvCell(v: unknown): string {
  if (v === null || v === undefined) return "";
  if (Array.isArray(v)) return JSON.stringify(v).replace(/"/g, '""');
  if (typeof v === "string") {
    const needsQuoting = /[",\n\r]/.test(v);
    const escaped = v.replace(/"/g, '""');
    return needsQuoting ? `"${escaped}"` : escaped;
  }
  return String(v);
}

function toCsvRow(columns: string[], row: Row): string {
  return columns.map((c) => {
    const v = row[c];
    if (typeof v === "string" && /[",\n\r]/.test(v)) {
      return `"${v.replace(/"/g, '""')}"`;
    }
    if (Array.isArray(v)) {
      return `"${JSON.stringify(v).replace(/"/g, '""')}"`;
    }
    return toCsvCell(v);
  }).join(",");
}

async function fetchAllMovies(): Promise<Row[]> {
  const all: Row[] = [];
  let from = 0;
  while (true) {
    const { data, error } = await supabase
      .from("movies")
      .select("*")
      .order("tmdb_id", { ascending: true })
      .range(from, from + PAGE - 1);
    if (error) throw error;
    if (!data || data.length === 0) break;
    all.push(...data);
    console.log(`  fetched ${all.length}...`);
    if (data.length < PAGE) break;
    from += PAGE;
  }
  return all;
}

async function main() {
  const outDir = resolve(__dirname, "../dataset");
  if (!existsSync(outDir)) mkdirSync(outDir, { recursive: true });

  console.log("Fetching movies from Supabase...");
  const movies = await fetchAllMovies();
  console.log(`Total: ${movies.length} movies.`);

  // Drop ephemeral/internal columns
  const exclude = new Set(["created_at", "updated_at"]);
  const columns = Object.keys(movies[0]).filter((c) => !exclude.has(c));

  // JSONL
  const jsonlPath = resolve(outDir, `mooduel-v${DATASET_VERSION}.jsonl`);
  const jsonlLines = movies.map((m) => {
    const row: Row = {};
    for (const c of columns) row[c] = m[c];
    return JSON.stringify(row);
  });
  writeFileSync(jsonlPath, jsonlLines.join("\n") + "\n");
  console.log(`Wrote ${jsonlPath}`);

  // CSV
  const csvPath = resolve(outDir, `mooduel-v${DATASET_VERSION}.csv`);
  const csvLines = [columns.join(",")];
  for (const m of movies) csvLines.push(toCsvRow(columns, m));
  writeFileSync(csvPath, csvLines.join("\n") + "\n");
  console.log(`Wrote ${csvPath}`);

  console.log("\nDone. Next: upload to HuggingFace with `huggingface-cli upload`.");
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});
